create table public.quotes (id uuid primary key default gen_random_uuid(), request_id uuid not null unique references public.requests(id) on delete restrict, current_revision_id uuid, created_at timestamptz not null default now());
create table public.quote_revisions (id uuid primary key default gen_random_uuid(), quote_id uuid not null references public.quotes(id) on delete restrict, revision_number integer not null, status text not null default 'draft', currency text not null default 'EUR', subtotal_cents integer not null default 0, discount_cents integer not null default 0, total_cents integer not null default 0, deposit_cents integer not null default 0, conditions text not null default '', published_at timestamptz, created_at timestamptz not null default now(), unique(quote_id, revision_number), constraint quote_revision_status check (status in ('draft','published','withdrawn')));
alter table public.quotes add constraint quotes_current_revision_fk foreign key (current_revision_id) references public.quote_revisions(id) on delete restrict;
create table public.quote_items (id uuid primary key default gen_random_uuid(), revision_id uuid not null references public.quote_revisions(id) on delete restrict, description text not null, quantity integer not null default 1, unit_price_cents integer not null default 0, total_cents integer not null default 0, sort_order integer not null default 0);
create table public.quote_responses (id uuid primary key default gen_random_uuid(), revision_id uuid not null references public.quote_revisions(id) on delete restrict, customer_user_id uuid not null references public.profiles(user_id) on delete restrict, outcome text not null, comment text not null default '', created_at timestamptz not null default now(), constraint quote_response_outcome check (outcome in ('accepted','rejected','changes_requested')));
alter table public.quotes enable row level security; alter table public.quote_revisions enable row level security; alter table public.quote_items enable row level security; alter table public.quote_responses enable row level security;
create policy "quotes staff" on public.quotes for all to authenticated using ((select public.current_staff_role()) is not null) with check ((select public.current_staff_role()) is not null);
create policy "quotes customer" on public.quotes for select to authenticated using (exists (select 1 from public.requests r where r.id = request_id and r.customer_user_id = (select auth.uid())));
create policy "revisions staff" on public.quote_revisions for all to authenticated using ((select public.current_staff_role()) = 'owner') with check ((select public.current_staff_role()) = 'owner');
create policy "revisions customer published" on public.quote_revisions for select to authenticated using (status = 'published' and exists (select 1 from public.quotes q join public.requests r on r.id=q.request_id where q.id=quote_id and r.customer_user_id=(select auth.uid())));
create policy "items staff" on public.quote_items for all to authenticated using ((select public.current_staff_role()) = 'owner') with check ((select public.current_staff_role()) = 'owner');
create policy "items customer published" on public.quote_items for select to authenticated using (exists (select 1 from public.quote_revisions v join public.quotes q on q.id=v.quote_id join public.requests r on r.id=q.request_id where v.id=revision_id and v.status='published' and r.customer_user_id=(select auth.uid())));
create policy "responses own" on public.quote_responses for select to authenticated using (customer_user_id=(select auth.uid()) or (select public.current_staff_role())='owner');
create policy "responses customer insert" on public.quote_responses for insert to authenticated with check (customer_user_id=(select auth.uid()));
create policy "responses owner" on public.quote_responses for all to authenticated using ((select public.current_staff_role())='owner') with check ((select public.current_staff_role())='owner');
grant select, insert, update, delete on public.quotes, public.quote_revisions, public.quote_items, public.quote_responses to authenticated;
